    function CheckAndChangeTab(menu, screenType, callback) {
        let req = {
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || 0,
            "ScreenType": screenType
        };

        eHnoteSurgeryService.GetActiveChartUser(req).then(function (resp) {
            if (resp.data.Message === "Success") {
                let data =
                    resp.data.rows || [];

                let anotherUser =
                    data.filter(x =>

                        x.UserId !=
                        $scope.UserId &&

                        x.Status ==
                        'Active'
                    );

                if (anotherUser.length > 0) {
                    alertify.error(
                        "Currently chart editing by "
                        + anotherUser[0]
                            .UserName
                    );

                    return;
                }

                let sameUser =
                    data.filter(x =>
                        x.UserId == $scope.UserId
                    );

                if (sameUser.length > 0) {
                    $scope.ActiveChartUserObj.ActiveChartUserId = sameUser[0].ActiveChartUserId;
                }

                // always call add/update
                AddUpdateActiveChartUser(
                    screenType,
                    'Active'
                );

                callback(menu);
            }
        },
            function () {
                AddUpdateActiveChartUser(screenType, 'Active');
                callback(menu);
            });
    }

    $scope.ChangeTab = function (menu) {

        if (menu == 4) {
            let screenType = '';

            if ($scope.TabObj.SelectedTab == 2) {
                screenType =
                    $scope.TabObj.PreopSUBTAB == 1
                        ? 'PreOpNurse'
                        : 'PreOpAnesthesia';
            }
            else if ($scope.TabObj.SelectedTab == 3) {
                screenType =
                    $scope.TabObj.IntraopSUBTAB == 2
                        ? 'IntraOpNurse'
                        : 'IntraOpAnesthesia';
            }

            if (screenType && $scope.ActiveChartUserObj.ActiveChartUserId > 0) {
                AddUpdateActiveChartUser(screenType, 'Complete');
            }
        }

        if (menu === 2 || menu === 3) {

            let screenType = menu === 2
                ? ($scope.TabObj.PreopSUBTAB === 1 ? 'PreOpNurse' : 'PreOpAnesthesia')
                : ($scope.TabObj.IntraopSUBTAB === 2 ? 'IntraOpNurse' : 'IntraOpAnesthesia');

            CheckAndChangeTab(menu, screenType, $scope.ChangeSelectedTab);
            return;
        }

        $scope.ChangeSelectedTab(menu);
    };

    $scope.ChangeSubTab = function (val,type) {


        // entering Intra Nurse
        if (type == 'IntraNurse') {
            CheckAndChangeTab(val,'IntraOpNurse',
                function () {
                    $scope.TabObj.IntraopSUBTAB = 2;
                });

            return;
        }

        if (type == 'IntraAnesthesia') {
            CheckAndChangeTab(val, 'IntraOpAnesthesia',
                function () {
                    $scope.TabObj.IntraopSUBTAB = 1;
                });

            return;
        }
        if (type == 'PreNurse') {
            CheckAndChangeTab(val, 'PreOpNurse',
                function () {
                    $scope.TabObj.PreopSUBTAB = 1;
                });

            return;
        }

        if(type == 'PreAnesthesia'){
            CheckAndChangeTab(val, 'PreOpAnesthesia',
                function () {
                    $scope.TabObj.PreopSUBTAB = 2;
                });

            return;
        }

        if (type == 'PostNurse') {
            $scope.TabObj.PostopSUBTAB = 1;
        } else if (type =='PostAnesthesia'){
            $scope.TabObj.PostopSUBTAB = 2;
        }

        if ($scope.TabObj.PreopSUBTAB == 1 || $scope.TabObj.PreopSUBTAB == 2) {
            $scope.$broadcast('clearPreOpData');
        } else if ($scope.TabObj.IntraopSUBTAB == 1 || $scope.TabObj.IntraopSUBTAB == 2) {
            $scope.$broadcast('clearPreOpData');
        }
      
    }

