    $scope.PreAdminCheckListObj = $scope.GetPreAdmChecklistObj();

    $scope.PreAdmissionSummaryInds = function (type) {
        if (type == 'ROS Main') {
            if ($scope.PreAdminCheckListObj.IsPreAdmROSMainInd) {
                $scope.PreAdminCheckListObj.IsPrAdmROSSystemicInd = true;
                $scope.PreAdminCheckListObj.IsPrAdmROSSurgicalInd = true;
                $scope.PreAdminCheckListObj.IsPrAdmROSAllergiesInd = true;
            }
            else {
                $scope.PreAdminCheckListObj.IsPrAdmROSSystemicInd = false;
                $scope.PreAdminCheckListObj.IsPrAdmROSSurgicalInd = false;
                $scope.PreAdminCheckListObj.IsPrAdmROSAllergiesInd = false;
            }
        }
        if (type == 'Evaluation') {
            if ($scope.PreAdminCheckListObj.IsPreAdmEvaluationMainInd) {
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationLabInd = true;
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationCardioInd = true;
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationAirwayInd = true;
            }
            else {
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationLabInd = false;
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationCardioInd = false;
                $scope.PreAdminCheckListObj.IsPrAdmEvaluationAirwayInd = false;
            }
        }
        if (type == 'Checklists') {
            if ($scope.PreAdminCheckListObj.IsPreAdmChecklistMainInd) {
                $scope.PreAdminCheckListObj.IsPreAdmChecklistHealthPlanInd = true;
            }
            else {
                $scope.PreAdminCheckListObj.IsPreAdmChecklistHealthPlanInd = false;

            }
        }
        if (type == 'PreSurgeryOrders') {
            if ($scope.PreAdminCheckListObj.IsPreAdmPreSurgeryOrdersMainInd) {
                $scope.PreAdminCheckListObj.IsPreAdmPreSurgeryMedicationsInd = true;
                $scope.PreAdminCheckListObj.IsPreAdmCurrentMedicationsInd = true;
                $scope.PreAdminCheckListObj.IsPreAdmLabsInvestigationsInd = true;
            }
            else {
                $scope.PreAdminCheckListObj.IsPreAdmPreSurgeryMedicationsInd = false;
                $scope.PreAdminCheckListObj.IsPreAdmCurrentMedicationsInd = false;
                $scope.PreAdminCheckListObj.IsPreAdmLabsInvestigationsInd = false;
            }
        }
        if (type == 'AnesthetistPlan') {
            if ($scope.PreAdminCheckListObj.IsPreAdmAnesthetistPlanMainInd) {
                $scope.PreAdminCheckListObj.IsPreAdmPreviousAnestheticInd = true;
                $scope.PreAdminCheckListObj.IsPreAdmAssessmentASAInd = true;
                $scope.PreAdminCheckListObj.IsPreAdmAnestheticPlanInd = true;
            }
            else {
                $scope.PreAdminCheckListObj.IsPreAdmPreviousAnestheticInd = false;
                $scope.PreAdminCheckListObj.IsPreAdmAssessmentASAInd = false;
                $scope.PreAdminCheckListObj.IsPreAdmAnestheticPlanInd = false;
            }
        }
    }
    $scope.PreAdmissionSummaryViewTemplate = function () {
        let AppointmentTypeIds = "4,7,6,14";
        let object = {
            "PatientID": $scope.cacheStorageItem.PatientID,
            "HospitalID": $scope.HospitalId,
            "AppointmentTypeIds": AppointmentTypeIds
        };
        eHnotePatientDataService.GetAppointmentsForCaseHistory(object).then(function (resp) {
            if (resp.data.length > 0) {
                $scope.RecentAppoinmentList = [];
                $scope.RecentAppoinmentList = resp.data || [];
                $scope.PreAdmissionApptsList = $filter('filter')($scope.RecentAppoinmentList, { 'AppointmentTypeId': 7 }, true);
                $scope.PreAdmisionNewSummary();
            }
        });
    }
