                $scope.ClearSurgery = function (item, index) {
                    item.PatientOrderId = item.PatientOrderId || 0;
                    if (item.PatientOrderId != 0) {
                        item.DeleteInd = "Y";
                    } else {
                        $scope.ApptSurgeryDetails.splice(index, 1);
                    }
                }
                $scope.RemoveAdditionalSurgery = function (item) {
                    item.PatientAdditionalSurgeryId = item.PatientAdditionalSurgeryId || 0;
                    if (item.PatientAdditionalSurgeryId != 0) {
                        item.DeleteInd = "Y";
                    } else {
                        var index = $scope.ApptAdditionalSurgeryDetails.indexOf(item);
                        if (index > -1) {
                            $scope.ApptAdditionalSurgeryDetails.splice(index, 1);
                        }
                        
                    }
                }
                $scope.RemoveDiagnosis = function (Mainitem, item) {
                    item.ConsultationDiagnosisId = item.ConsultationDiagnosisId || 0;
                    /*if (item.DiagnosisDetailId != 0) {*/
                    if (item.ConsultationDiagnosisId != 0) {
                        item.DeleteInd = "Y";
                    } else {
                        var index = Mainitem.DiagnosisList.indexOf(item);
                        if (index > -1) {
                            Mainitem.DiagnosisList.splice(index, 1);
                        }
                        
                    }
                }


                $scope.selectBasicInfoImgs = function (files) {
                    files = files || [];
                    if (files.length > 0) {
                        angular.forEach(files, function (item) {
                            $scope.file = item;
                            if ($scope.file != null) {

                                var pName = $scope.file.name, name = "";
                                var type = $scope.file.type.split("/")[1];
                                if (pName.length > 9) {
                                    name = pName.substring(0, 9) + "..." + "." + type;
                                } else {
                                    name = angular.copy(pName) + '.' + type;
                                }
                                var obj = {
                                    "file": $scope.file,
                                    "DocumentID": 0,
                                    "DisplayName": $scope.file.name || "",
                                    "FileName": $scope.file.name || "",
                                    "FileExt": $scope.file.type,
                                    "S3URL": "",
                                    "DeleteInd": false,
                                    "FileTypeId": 35,
                                };

                                $scope.EditSurgeryObj.TempImagesArray.push(obj);

                                angular.element("input[type='file']").val(null);
                            }
                        });
                    }
                };

                $scope.ApptSurgeryDetails = $scope.ApptSurgeryDetails || [];
