                $scope.GetOrganizationProcedure = function (text) {
                    
                    var params = {
                        "OrganizationId": $scope.HospitalId,
                        "ProcedureId": 0,
                        "CPTCODE": "",  
                        "SearchText": text || "",
                        "TypeOfServiceId": 0,
                        "PageNumber": 1,
                        "PageSize": 10,
                        "Status": 1,
                        "IsFrequent": "N"
                    };
                    if (params.SearchText == '') {
                        params.IsFrequent = 'Y';
                    }
                    return eHnoteSettingsDataService.GetOrganizationProcedures(params).then(function (resp) {
                        if (resp.data.rows !== undefined) {
                            return resp.data.rows.map(function (item) {
                                return item;
                            });
                        }
                    });
                };

                $scope.pushtoBill = function (item) {
                    var OrganizationPayorId = 0;
                    $scope.selectobj = {
                        "OrganizationProcedureId": item.OrganizationProcedureId,
                        "ProcedureId": item.ProcedureId,
                        "CPTCode": item.CPTCode,
                        "ProcedureName": item.ProcedureName,
                        "DeleteInd": "N",
                        "ProcedureCost": null,
                        "DeleteInd": 'N',
                        "CordinatorBillItemListId": 0,
                        "Units": 1,
                        "Charges": null,
                        "InsuranceAmount": null,
                        "PatientCoPay": null,
                        "Total": 0
                    };

                    var List = $filter("filter")($scope.OrdersObj.BillItemList, function (Aitem) {
                        return (Aitem.OrganizationProcedureId === item.OrganizationProcedureId && Aitem.DeleteInd === 'N');
                    });
                    if (List.length > 0) {
                        alertify.error('Bill Item Already Added!');
                        $scope.OrdersObj.BillParticular = "";
                        return;
                    }

                    var req = {
                        "ParentOrganizationId": $scope.ParenthospitalId,
                        "OrganizationId": $scope.HospitalId,
                        "OrganizationPayorId": OrganizationPayorId || 0,
                        "OrganizationProcedureId": item.OrganizationProcedureId || 0
                    };

                    eHnoteSettingsDataService.GetOrganizationProcedureCostById(req).then(function (resp) {
                        if (resp.data.Status === "Success") {
                            var ProcedureCost = 0;
                            if (resp.data.rows.length > 0) {
                                ProcedureCost = resp.data.rows[0].ActualCost || 0;
                            }
                            $scope.selectobj.ProcedureCost = ProcedureCost;
                            $scope.OrdersObj.BillItemList.push($scope.selectobj);
                            $scope.OrdersObj.BillParticular = '';

                        } else {
                            alertify.error(resp.data.Message);
                        }

                    }, function (error) {

                    });
                }

                $scope.changePrice = function () {
                    $scope.OrdersObj.BillItemList = $scope.OrdersObj.BillItemList || [];
                    $scope.OrdersObj.TotalAmount = null;
                    $scope.OrdersObj.TotalChargeAmount = null;
                    if ($scope.OrdersObj.BillItemList.length > 0) {
                        angular.forEach($scope.OrdersObj.BillItemList, function (item) {
                            if (item.DeleteInd == 'N') {
                                var Quantity = 0;
                                var Price = 0; Quantity = item.Units;
                                Price = item.PatientCoPay;
                                if (Quantity > 0 && Price > 0) {
                                    item.Total = Quantity * Price;
                                } else {
                                    item.Total = 0;
                                }
                                /*item.PatientCoPay = parseFloat(item.PatientCoPay);*/

                                item.PatientCoPayRaw = item.PatientCoPay; 
                                item.PatientCoPayRaw = parseFloat(item.PatientCoPayRaw) || null;

                                if (item.PatientCoPayRaw != null) {
                                    $scope.OrdersObj.TotalAmount += item.Total;
                                    $scope.OrdersObj.TotalChargeAmount += item.Total;
                                }
                                //if (item.PatientCoPayRaw == null || item.Units == null) {
                                //    $scope.OrdersObj.TotalChargeAmount = '';
                                //}
                            };
                        });
                    }
                    $scope.OrdersObj.TotalChargeAmount = parseFloat($scope.OrdersObj.TotalChargeAmount.toFixed(2));
                }

                $scope.CordinatePrint = function (item, titem) {

                    titem.Age = titem.AgeInYears + 'Y' + ' ' + titem.AgeInMonths + 'M';
                    titem.MobileNo = titem.AltCountryCode + '-' + titem.Altareacode + '-' + titem.PatientHomeNumber;

                    var obj = {
                        "BillingType": "Billing Items",
                        "PrintedDatenTime": "",
                        "CordinatePrintInformation": item,
                        "PatientName": titem.FullName,
                        "PatientDisplayId": titem.PatientDisplayId,
                        "Gender": titem.Gender,
                        "Age": titem.Age,
                        "MobileNo": titem.MobileNo,
                    }

                    var printDate = $filter("date")(new Date(), "MMM-dd-yyyy");
                    var printTime = moment(new Date()).format("HH:mm");
                    var printDatemTime = printDate + '  ' + printTime;
                    obj.PrintedDatenTime = printDatemTime;
                    USPrintService.GenerateCordinatePrint(obj);

                }

                $scope.changeUploadedItemBillPrice = function () {
                    $scope.OrdersObj.FileUploadTotalAmount = 0;
                    if ($scope.OrdersObj.BillItemFileUploadList.length > 0) {
                        angular.forEach($scope.OrdersObj.BillItemFileUploadList, function (item) {
                            if (item.DeleteInd == 'N') {
                                item.BillItemPriceRaw = item.BillItemPrice;
                                item.BillItemPriceRaw = parseFloat(item.BillItemPriceRaw) || null;

                                $scope.OrdersObj.FileUploadTotalAmount += item.BillItemPriceRaw;
                                $scope.OrdersObj.FileUploadTotalAmount = parseFloat($scope.OrdersObj.FileUploadTotalAmount.toFixed(2));
                            };
                        });
                    }
                }

                $scope.DelectBillitem = function (item, index, type) {
                    type = type || ''
                    if (type == 'cpt') {
                        var index = $scope.OrdersObj.BillItemList.indexOf(item);
                        if (item.CordinatorBillItemListId == 0) {

                            $scope.OrdersObj.BillItemList.splice(index, 1);
                        } else {
                            $scope.OrdersObj.BillItemList[index].DeleteInd = 'Y';
                        }

                        $scope.changePrice();
                    } else if (type == 'file') {
                        var index = $scope.OrdersObj.BillItemFileUploadList.indexOf(item);
                        if (item.DocumentId == 0) {

                            $scope.OrdersObj.BillItemFileUploadList.splice(index, 1);
                        } else {
                            $scope.OrdersObj.BillItemFileUploadList[index].DeleteInd = 'Y';
                            $scope.OrdersObj.FileUploadTotalAmount = 0;
                            if ($scope.OrdersObj.BillItemFileUploadList.length > 0) {
                                angular.forEach($scope.OrdersObj.BillItemFileUploadList, function (Fitem) {
                                    if (Fitem.DeleteInd == 'N') {
                                        Fitem.BillItemPriceRaw = Fitem.BillItemPrice;
                                        Fitem.BillItemPriceRaw = parseFloat(Fitem.BillItemPriceRaw) || null;

                                        $scope.OrdersObj.FileUploadTotalAmount += Fitem.BillItemPriceRaw;
                                        $scope.OrdersObj.FileUploadTotalAmount = parseFloat($scope.OrdersObj.FileUploadTotalAmount.toFixed(2));
                                    };
                                });
                            }
                            var param = {
                                "OrgDescriptionId": item.OrgDescriptionId,
                                "PatientId": $scope.cacheStorageItem.PatientID,
                                "PatientName": $scope.cacheStorageItem.PatientName,
                                "AppointmentId": $scope.cacheStorageItem.appointmentid,
                                "DeleteInd": "Y",
                                "UserId": $scope.UserId,
                                "file": item.file,
                                "HospitalId": $scope.HospitalId,
                                "S3URL": item.S3URL,
                                "DocumentId": item.DocumentId,
                                "DocumentName": item.FileName,
                                "DocumentExt": item.FileExt,
                                "ConsultationID": $scope.cacheStorageItem.ConsultationID || 0,
                                "FileTypeId": 31,
                            };
                            eHnoteSurgeryService.AddUpdateCostEstimatorupload(param, item.file).then(function (resp) {
                                console.log(resp);
                                if (resp.status == 'Success') {
                                    $scope.OrdersObj.FileUploadTotalAmount = 0;
                                    if ($scope.OrdersObj.BillItemFileUploadList.length > 0) {
                                        angular.forEach($scope.OrdersObj.BillItemFileUploadList, function (Fitem) {
                                            if (Fitem.DeleteInd == 'N') {
                                                Fitem.BillItemPriceRaw = Fitem.BillItemPrice;
                                                Fitem.BillItemPriceRaw = parseFloat(Fitem.BillItemPriceRaw) || null;

                                                $scope.OrdersObj.FileUploadTotalAmount += Fitem.BillItemPriceRaw;
                                                $scope.OrdersObj.FileUploadTotalAmount = parseFloat($scope.OrdersObj.FileUploadTotalAmount.toFixed(2));
                                            };
                                        });
                                    }
                                }
                            }, function (error) {
                                console.log(error);
                            });
                        }
                    }
                };

